import { createComponent, createContext, JSXElement } from "solid-js";
import { createMutable } from "solid-js/store";
import { render } from "solid-js/web";

import { Focus } from "#core/ui/input/focus-support.js";

export type SolidRenderFunction = (attrs: Readonly<Record<string, string | null>>, element?: Element) => JSXElement;

export interface LegacySolidComponentOptions {
	attrs?: Record<string, string | null>;
	classNames?: string[];
	calleeURLOrPriority?: string | number;
	tabIndex?: number;
	initializeImmediately?: boolean;
}

interface LegacySolidComponentProps extends LegacySolidComponentOptions {
	renderFunction: SolidRenderFunction;
}

const registeredLegacySolidComponents = new Map<string, LegacySolidComponentProps>();

export class SolidAdapterContextProvider {
	constructor(public readonly rootElement: ComponentRoot<FxsSolidComponent>) {}
}
export const SolidAdapterContext = createContext<SolidAdapterContextProvider>();

class FxsSolidComponent extends Component {
	private dispose: (() => void) | null = null;
	private onActivatableFocusEventListener = this.onFocus.bind(this);
	private reactiveAttrs: Record<string, string | null> | undefined;

	private children: ChildNode[] | null = null;

	onAttach() {
		super.onAttach();
		this.Root.addEventListener("focus", this.onActivatableFocusEventListener);

		// Component may have been moved from one location to another, dipose and re-render.
		if (this.dispose) {
			this.dispose();
			this.dispose = null;

			if (this.children) {
				for (const c of this.children) {
					this.Root.append(c);
				}
			}
			this.children = null;
		}

		if (this.children == null) {
			this.children = [];
			for (const c of this.Root.childNodes) {
				this.children.push(c);
			}
		}

		const props = registeredLegacySolidComponents.get(this.Root.tagName);

		if (props) {
			// Merge Attributes with ones defined on FXS Component (Component has precendence)
			const attrs = { ...props.attrs };
			for (const attr in attrs) {
				if (this.Root.hasAttribute(attr)) {
					attrs[attr] = this.Root.getAttribute(attr);
				}
			}

			this.reactiveAttrs = createMutable(attrs);
			const renderSolidComponent = () => props.renderFunction(this.reactiveAttrs!, this.Root);
			this.dispose = render(
				() =>
					createComponent(SolidAdapterContext.Provider, {
						value: new SolidAdapterContextProvider(this.Root),
						get children() {
							return renderSolidComponent();
						},
					}),
				this.Root,
			);
		} else {
			console.error(
				`Could not resolve solid component name based on this element's tag name - ${this.Root.tagName}.`,
			);
		}
	}

	onAttributeChanged(_name: string, _oldValue: string | null, _newValue: string | null): void {
		if (this.reactiveAttrs) {
			this.reactiveAttrs[_name] = _newValue;
		}
	}

	onDetach() {
		super.onDetach();

		if (this.dispose) {
			// Store as a local and nullify to avoid recursive calls.
			const dispose = this.dispose;
			this.dispose = null;
			dispose();

			if (this.children) {
				for (const c of this.children) {
					this.Root.append(c);
				}
			}
			this.children = null;
		}
	}

	onFocus() {
		if (this.Root.hasChildNodes()) {
			Focus.setContextAwareFocus(this.Root.firstChild as Element, this.Root);
		}
	}

	onReceiveFocus(): void {
		super.onReceiveFocus();
		this.onFocus();
	}
}

/***
 * Wraps a solid component into a legacy component
 * @param name - The name of the legacy component to create
 * @param options - The component options to use when registering the component
 *   - attrs - A list of attributes with defaults the legacy component can have
 *             These will be tracked reactively and provided to the render function
 *   - classNames - A list of class names to apply to the legacy component
 *   - calleeURLOrPriority - A URL or priority, used in determining override order of the legacy component
 *   - tabIndex - The tab index to apply to the legacy component
 * @param renderFunction - The solid js component render function
 *   - This will be called in a reactive scope
 *   - The first parameter attr is a reactive proxy to the legacy component attributes - these must first be defined in options.attrs.
 *   - The second paramter element is the root element of the legacy component
 */
export function defineLegacyComponent(
	name: string,
	options: LegacySolidComponentOptions,
	renderFunction: SolidRenderFunction,
): void {
	if (!renderFunction) {
		throw new Error("defineLegacyComponent - A render function must be defined!");
	}

	const ranking =
		typeof options.calleeURLOrPriority == "number"
			? options.calleeURLOrPriority
			: options.calleeURLOrPriority
				? Modding.getModRankByURL(options.calleeURLOrPriority)
				: 1;

	const componentAttrs = options.attrs
		? Object.getOwnPropertyNames(options.attrs).map((attr) => ({ name: attr }) as ComponentAttributeDefinition)
		: [];

	registeredLegacySolidComponents.set(name.toUpperCase(), { renderFunction, ...options });

	Controls.define(name, {
		createInstance: FxsSolidComponent,
		classNames: options.classNames,
		skipPostOnAttach: true,
		priority: ranking >= 0 ? ranking : 0,
		attributes: componentAttrs,
		tabIndex: options?.tabIndex,
		initializeImmediately: options?.initializeImmediately,
	});
}
